-- 4. Bridge B2: 123 Turkish TYT & Hard AYT Question Bank Items (ADR-006 training_eligible=FALSE)
INSERT INTO exam_question_bank_items (
    id, exam_definition_id, exam_version_number, exam_section_id,
    question_code, topic_code, subtopic_code, item_format,
    difficulty_band, difficulty_b_value, discrimination_a_value, guessing_c_value,
    cognitive_level, stem_markdown, stem_latex, alt_text_description, has_visual_diagram,
    numeric_correct_answer, numeric_tolerance, structured_rubric_json,
    solution_explanation_markdown, estimated_time_seconds, max_points, negative_marking_weight,
    status, content_sha256, exposure_count, training_eligible
) VALUES
(
    '93000000-0000-4000-8000-200000000001', '91000000-0000-4000-8000-000000000201', 2, '92000000-0000-4000-8000-000000000201',
    'TYT-TR-2026-WP-NF-001', 'MATH.WORD_PROBLEMS.NUMBER_FRACTION', 'KESIR_COZUMLEME', 'SINGLE_CHOICE_MCQ',
    'EASY', -1.10, 1.05, 0.20,
    'APPLICATION', 'Bir kargo şirketinin şubesinde bulunan paketlerin $\frac{2}{5}$''i İstanbul''a, kalan paketlerin $\frac{1}{3}$''ü Ankara''ya gönderilmiştir. Şubede geriye $24$ paket kaldığına göre, başlangıçta şubede toplam kaç paket vardır?', '\left(1 - \frac{2}{5}\right)\left(1 - \frac{1}{3}\right)x = 24', NULL, FALSE,
    NULL, NULL, '{"expectedAnswerLatex": "60", "sympyCheckExpr": "60", "isNewGenProblem": true, "locale": "tr-TR"}'::jsonb,
    'Kalan oran $\frac{3}{5} \cdot \frac{2}{3} = \frac{2}{5}$ olur. $\frac{2}{5}x = 24$ ise $x = 60$ paket bulunur.', 90, 1.00, 0.2500, 'PUBLISHED',
    'e589ce8c08cc03110b4a1c918342853345b5062c73333b537f4372f84a590261', 0, FALSE
),
(
    '93000000-0000-4000-8000-200000000002', '91000000-0000-4000-8000-000000000201', 2, '92000000-0000-4000-8000-000000000201',
    'TYT-TR-2026-WP-NF-002', 'MATH.WORD_PROBLEMS.NUMBER_FRACTION', 'ESIT_PARCA_KURGU', 'SINGLE_CHOICE_MCQ',
    'MEDIUM', 0.10, 1.20, 0.20,
    'APPLICATION', 'Bir marangoz elindeki tahta çubuğu önce $8$ eş parçaya bölüyor. Eğer aynı çubuğu $6$ eş parçaya bölseydi her bir parça $5\text{ cm}$ daha uzun olacaktı. Buna göre tahta çubuğun toplam uzunluğu kaç santimetredir?', '\frac{L}{6} - \frac{L}{8} = 5', NULL, FALSE,
    NULL, NULL, '{"expectedAnswerLatex": "120", "sympyCheckExpr": "120", "isNewGenProblem": true, "locale": "tr-TR"}'::jsonb,
    '$\frac{L}{6} - \frac{L}{8} = 5 \Rightarrow \frac{4L - 3L}{24} = 5 \Rightarrow L = 120\text{ cm}$ bulunur.', 95, 1.00, 0.2500, 'PUBLISHED',
    '35b50550255132034003ff13abd8704444a0acd79fb3b9d421d54416085e34af', 0, FALSE
),
(
    '93000000-0000-4000-8000-200000000003', '91000000-0000-4000-8000-000000000201', 2, '92000000-0000-4000-8000-000000000201',
    'TYT-TR-2026-WP-NF-003', 'MATH.WORD_PROBLEMS.NUMBER_FRACTION', 'ASANSOR_KAPASITE', 'SINGLE_CHOICE_MCQ',
    'HARD', 1.15, 1.35, 0.20,
    'ANALYSIS', 'Bir apartman asansörünün taşıma kapasitesi yalnızca yetişkinlerden oluştuğunda $12$ kişi, yalnızca çocuklardan oluştuğunda ise $20$ kişidir. Bu asansöre $9$ yetişkin bindiğinde asansörün kalan kapasitesiyle en fazla kaç çocuk daha asansöre binebilir?', '\frac{9}{12} + \frac{c}{20} \le 1', NULL, FALSE,
    NULL, NULL, '{"expectedAnswerLatex": "5", "sympyCheckExpr": "5", "isNewGenProblem": true, "locale": "tr-TR"}'::jsonb,
    '$9$ yetişkin kapasitenin $\frac{9}{12} = \frac{3}{4}$''ünü doldurur. Kalan $\frac{1}{4}$ kapasite $\frac{1}{4} \cdot 20 = 5$ çocuğa karşılık gelir.', 110, 1.00, 0.2500, 'PUBLISHED',
    'b1265dc13da5df42c7b0d9d023a739ec491a4adfaa9981068618ec6d6d8b500c', 0, FALSE
),
(
    '93000000-0000-4000-8000-200000000004', '91000000-0000-4000-8000-000000000201', 2, '92000000-0000-4000-8000-000000000201',
    'TYT-TR-2026-WP-NF-004', 'MATH.WORD_PROBLEMS.NUMBER_FRACTION', 'BATARYA_TUKETIM', 'SINGLE_CHOICE_MCQ',
    'EXPERT', 1.85, 1.50, 0.20,
    'EVALUATION', 'Tam şarjlı bir dizüstü bilgisayarın bataryası yalnızca video izlendiğinde $4$ saatte, yalnızca belge düzenlendiğinde ise $10$ saatte tamamen tükenmektedir. Bataryası tam dolu iken $2$ saat video izleyen bir öğrenci, ardından belge düzenlemeye geçerse kalan batarya ile kaç saat daha belge düzenleyebilir?', '\frac{2}{4} + \frac{t}{10} = 1', NULL, FALSE,
    NULL, NULL, '{"expectedAnswerLatex": "5", "sympyCheckExpr": "5", "isNewGenProblem": true, "locale": "tr-TR"}'::jsonb,
    '$2$ saat video bataryanın $\frac{2}{4} = \frac{1}{2}$''sini tüketir. Kalan $\frac{1}{2}$ batarya ile $\frac{1}{2} \cdot 10 = 5$ saat belge düzenlenir.', 120, 1.00, 0.2500, 'PUBLISHED',
    'c1e8a2425fca43753e69228e75c5aec5f92f04db99bb87c6aa2dc13b3daae544', 0, FALSE
),
(
    '93000000-0000-4000-8000-200000000005', '91000000-0000-4000-8000-000000000201', 2, '92000000-0000-4000-8000-000000000201',
    'TYT-TR-2026-WP-RP-001', 'MATH.WORD_PROBLEMS.RATIO_PROPORTION', 'DOGURU_ORANTI_TARIF', 'SINGLE_CHOICE_MCQ',
    'EASY', -1.10, 1.05, 0.20,
    'COMPREHENSION', 'Bir fırında hazırlanan kurabiye hamurunda un, şeker ve tereyağı kütleleri sırasıyla $5$, $2$ ve $3$ sayılarıyla doğru orantılıdır. Toplam $1200\text{ gram}$ hamur hazırlandığında kullanılan un miktarı tereyağı miktarından kaç gram fazladır?', '5k + 2k + 3k = 1200,\; 5k - 3k = ?', NULL, FALSE,
    NULL, NULL, '{"expectedAnswerLatex": "240", "sympyCheckExpr": "240", "isNewGenProblem": true, "locale": "tr-TR"}'::jsonb,
    '$10k = 1200 \Rightarrow k = 120\text{ g}$. Un ile tereyağı farkı $5k - 3k = 2k = 240\text{ g}$ bulunur.', 80, 1.00, 0.2500, 'PUBLISHED',
    '57415f4b355c16df05b17be91607af4be2757b7041d0fc1c052ab1bf72051fad', 0, FALSE
),
(
    '93000000-0000-4000-8000-200000000006', '91000000-0000-4000-8000-000000000201', 2, '92000000-0000-4000-8000-000000000201',
    'TYT-TR-2026-WP-RP-002', 'MATH.WORD_PROBLEMS.RATIO_PROPORTION', 'TERS_ORANTI_DISLI', 'SINGLE_CHOICE_MCQ',
    'MEDIUM', 0.10, 1.20, 0.20,
    'APPLICATION', 'Birbirini döndüren üç dişli çarktan birincisi $3$, ikincisi $4$, üçüncüsü ise $6$ devir yaptığında aynı konuma gelmektedir. Bu üç çarkın toplam diş sayısı $135$ olduğuna göre, en fazla dişe sahip olan çarkın diş sayısı kaçtır?', '3d_1 = 4d_2 = 6d_3 = 12k,\; d_1 + d_2 + d_3 = 135', NULL, FALSE,
    NULL, NULL, '{"expectedAnswerLatex": "60", "sympyCheckExpr": "60", "isNewGenProblem": true, "locale": "tr-TR"}'::jsonb,
    'Devir sayısı ile diş sayısı ters orantılıdır: $d_1=4k, d_2=3k, d_3=2k$. Toplam $9k=135 \Rightarrow k=15$. En büyük çark $4k=60$ dişlidir.', 100, 1.00, 0.2500, 'PUBLISHED',
    'aa74dc929245b893f5ee8b82e2370b306be8fa1528c1810fa3eea2d9cf208dbd', 0, FALSE
