(
    '93000000-0000-4000-8000-200000000007', '91000000-0000-4000-8000-000000000201', 2, '92000000-0000-4000-8000-000000000201',
    'TYT-TR-2026-WP-RP-003', 'MATH.WORD_PROBLEMS.RATIO_PROPORTION', 'KARISIM_ORAN', 'SINGLE_CHOICE_MCQ',
    'MEDIUM', 0.10, 1.20, 0.20,
    'APPLICATION', 'Bir kafede hazırlanan özel kahve karışımında süt miktarının kahve özütü miktarına oranı $\frac{7}{3}$''tür. $300\text{ mL}$ karışımın içine yalnızca $60\text{ mL}$ daha süt eklendiğinde yeni karışımda süt miktarının kahve özütü miktarına oranı kaç olur?', '\frac{210 + 60}{90}', NULL, FALSE,
    NULL, NULL, '{"expectedAnswerLatex": "3", "sympyCheckExpr": "3", "isNewGenProblem": true, "locale": "tr-TR"}'::jsonb,
    '$300\text{ mL}$ karışımda $210\text{ mL}$ süt ve $90\text{ mL}$ kahve özütü vardır. $60\text{ mL}$ süt eklenince $\frac{270}{90} = 3$ olur.', 90, 1.00, 0.2500, 'PUBLISHED',
    'd9c6b940363679dcc64f9f67a0401752493d2501194ba10c9e7fa482fcfe3a26', 0, FALSE
