    'MEDIUM', 0.10, 1.20, 0.20,
    'APPLICATION', 'Beş basamaklı $4a73b$ doğal sayısının $15$ ile bölümünden kalan $2$''dir. Bu koşulu sağlayan tüm $4a73b$ sayıları için $a$''nın alabileceği en büyük değer ile en küçük değerin toplamı kaçtır?', '4a73b \equiv 2 \pmod{15}', NULL, FALSE,
    NULL, NULL, '{"expectedAnswerLatex": "9", "sympyCheckExpr": "9", "isNewGenProblem": false, "locale": "tr-TR"}'::jsonb,
    '$15$ ile bölümünden kalan $2$ ise sayı $5$ ile bölünürken kalan $2$ ($b \in \{2, 7\}$) ve $3$ ile bölünürken kalan $2$ olmalıdır. $b=2$ için $16+a \equiv 2 \pmod 3 \Rightarrow a \in \{1,4,7\}$; $b=7$ için $21+a \equiv 2 \pmod 3 \Rightarrow a \in \{2,5,8\}$. Böylece $a_{\min}=1$ ve $a_{\max}=8$ olup toplamları $1+8=9$ bulunur.', 100, 1.00, 0.2500, 'PUBLISHED',
    '4623b23f09d9b1eec1f22b021b8771f0af53c448dcc1caeae2331edd7ed606a2', 0, FALSE
),
