    'MEDIUM', 0.10, 1.20, 0.20,
    'APPLICATION', '$i^2 = -1$ olmak üzere, $z = \frac{4 + 2i}{1 - i}$ karmaşık sayısının sanal (imajiner) kısmı ile gerçel (reel) kısmının toplamı kaçtır?', '\text{Re}\left(\frac{4 + 2i}{1 - i}\right) + \text{Im}\left(\frac{4 + 2i}{1 - i}\right)', NULL, FALSE,
