    'HARD', 1.15, 1.35, 0.20,
    'ANALYSIS', '$\log_2(x - 1) + \log_2(x - 3) = 3$ denklemini sağlayan $x$ gerçel sayılarının toplamı kaçtır?', '\log_2((x-1)(x-3)) = 3,\; x > 3', NULL, FALSE,
