    'AYT-TR-2026-AL-LOG-005', 'MATH.ALGEBRA.LOGARITHMS_EXPONENTIAL', 'LOGARITMA_TABAN_KISITI', 'SINGLE_CHOICE_MCQ',
    'HARD', 1.15, 1.35, 0.20,
    'ANALYSIS', '$\log_{x-2}(x^2 - 4x + 4) = 2$ denklemi $x > 2, x \neq 3$ tanım kümesinde incelendiğinde, eğer denklem $\log_{x-2}(x + 4) = 2$ olsaydı bu denklemi sağlayan $x$ değeri kaç olurdu?', '(x - 2)^2 = x + 4,\; x > 2,\; x \neq 3', NULL, FALSE,
    NULL, NULL, '{"expectedAnswerLatex": "5", "sympyCheckExpr": "5", "isNewGenProblem": false, "locale": "tr-TR"}'::jsonb,
    '$(x - 2)^2 = x + 4 \Rightarrow x^2 - 4x + 4 = x + 4 \Rightarrow x^2 - 5x = 0 \Rightarrow x = 0$ veya $x = 5$. Taban şartı $x - 2 > 0 \Rightarrow x > 2$ ve $x - 2 \neq 1 \Rightarrow x \neq 3$ olduğundan $x = 0$ elenir ve tek çözüm $x = 5$ bulunur.', 100, 1.00, 0.2500, 'PUBLISHED',
    '8ee635ce2eebecd3b4211881e7b08716b1defdc65531fa7ef3994ede407f3ef0', 0, FALSE
),
(
