    'AYT-TR-2026-AL-ABS-001', 'MATH.ALGEBRA.ABSOLUTE_VALUE', 'MUTLAK_DEGER_KOK_KISITI', 'SINGLE_CHOICE_MCQ',
    'MEDIUM', 0.10, 1.20, 0.20,
    'APPLICATION', '$|x - 3| = 2x - 9$ denkleminin çözüm kümesindeki $x$ değeri kaçtır?', '|x - 3| = 2x - 9,\; 2x - 9 \ge 0', NULL, FALSE,
    NULL, NULL, '{"expectedAnswerLatex": "6", "sympyCheckExpr": "6", "isNewGenProblem": false, "locale": "tr-TR"}'::jsonb,
    'Sağ taraf $2x - 9 \ge 0 \Rightarrow x \ge 4{,}5$ olmalıdır. $x - 3 = 2x - 9 \Rightarrow x = 6$ ($\ge 4{,}5$, geçerli). Diğer dal $-(x-3) = 2x - 9 \Rightarrow 3x = 12 \Rightarrow x = 4$ ($< 4{,}5$, yalancı kök). Tek çözüm $x = 6$''dır.', 95, 1.00, 0.2500, 'PUBLISHED',
    '8595987ab5c3244e44ce8d8ba8a56afd1a99d8f71ad986437b3fb84ed14b09d1', 0, FALSE
