    'HARD', 1.15, 1.35, 0.20,
    'ANALYSIS', '$||x - 2| - 4| = 3$ denklemini sağlayan tüm $x$ gerçel sayılarının toplamı kaçtır?', '|x - 2| \in \{7, 1\}', NULL, FALSE,
    NULL, NULL, '{"expectedAnswerLatex": "8", "sympyCheckExpr": "8", "isNewGenProblem": false, "locale": "tr-TR"}'::jsonb,
    '$|x - 2| - 4 = 3 \Rightarrow |x - 2| = 7 \Rightarrow x \in \{9, -5\}$ (toplam $4$). $|x - 2| - 4 = -3 \Rightarrow |x - 2| = 1 \Rightarrow x \in \{3, 1\}$ (toplam $4$). Tüm köklerin toplamı $9 - 5 + 3 + 1 = 8$''dir.', 105, 1.00, 0.2500, 'PUBLISHED',
